import{_ as s,o as t,c as a,a5 as o}from"./chunks/framework.BYXPg_yw.js";const k=JSON.parse('{"title":"Wheel Control — Python Example","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"software/sdk/python/wheel.md","filePath":"software/sdk/python/wheel.md","lastUpdated":1793350928000}'),n={name:"software/sdk/python/wheel.md"};function i(r,e,l,h,p,d){return t(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="wheel-control-—-python-example" tabindex="-1">Wheel Control — Python Example <a class="header-anchor" href="#wheel-control-—-python-example" aria-label="Permalink to &quot;Wheel Control — Python Example&quot;">​</a></h1><p><strong>Source</strong>: <code>rbq_sdk/python/example/sport/rbq_wheel.py</code></p><p>Python port of the C++ <a href="/RBQ/nightly/software/sdk/cpp/wheel.html">Wheel Control</a>. Spins the four wheels of an <strong>RBQ wheel robot (RBQ-W)</strong> from <strong>app slot 21</strong> by publishing <code>MotionRef_</code> on <code>rt/rbq/ref/motion/_21</code> after taking ownership of the wheel joints only, then releases them.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><ol><li>Reads <code>interface</code> and optional <code>torque kd seconds</code> from the command line.</li><li>Calls <code>ChannelFactoryInitialize(0, interface)</code>, then creates <code>ChannelPublisher(&quot;rt/rbq/ref/motion/_21&quot;, MotionRef_)</code>, <code>ChannelPublisher(&quot;rt/rbq/cmd/motion/owner/_21&quot;, JointOwnershipCmd_)</code> and <code>ChannelSubscriber(&quot;rt/rbq/ref/motion/_0&quot;, MotionRef_)</code> for the reference the robot applies.</li><li>Waits ~0.5 s for DDS discovery, publishes a first zero-torque reference, then sends <code>JointOwnershipCmd_</code> with <code>whl_joint = [True] * 4</code>.</li><li>Publishes <code>whl_joint</code> at 500 Hz with <code>kp = 0</code>, the given <code>kd</code> and a torque ramped from 0 over 0.5 s, printing the applied wheel reference every 0.5 s.</li><li>When time is up (or on Ctrl+C) it sets the torque to 0 for 0.5 s, then publishes <code>kp = kd = torque = 0</code> and exits.</li></ol><p>A free wheel settles at <strong>velocity = torque / kd</strong> [rad/s]. Gains are physical values on both CAN FD and classic CAN robots — Network converts them for the board. It runs next to <a href="/RBQ/nightly/software/sdk/python/low-level.html">Low Level (Python)</a>, which uses slot 20.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>On the ground the robot <strong>rolls</strong> while the wheels turn. Give it room, start with a small torque, and keep the remote E-Stop at hand.</p></div><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li><code>rbq_sdk_py</code> importable — see <a href="/RBQ/nightly/software/sdk/python/overview.html">Python SDK Overview</a>.</li><li>The robot stack running on the same DDS interface.</li><li><strong>An RBQ wheel robot (RBQ-W)</strong>, standing. In the simulator start Motion and MuJoCo with <code>--wheel</code> (<code>bash scripts/sim.bash --robot wheel</code>).</li></ul><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> RBQ/rbq_sdk/python/example/sport</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rbq_wheel.py</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [networkInterface] [torque] [kd] [seconds]</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2 rad/s forward for 3 s (the defaults) — the interface always comes first:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rbq_wheel.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eth0</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Backward, 1 rad/s, for 5 s:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rbq_wheel.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eth0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -0.5</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.5</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span></span></code></pre></div><p>All arguments are positional, so <strong>the interface must be the first argument</strong>.</p><p>Arguments, defaults and what happens after the example exits are the same as in the <a href="/RBQ/nightly/software/sdk/cpp/wheel.html#run">C++ version</a>. Use the interface that reaches the robot — <code>lo</code> when running on the robot PC, your NIC from another host.</p><h2 id="example-output" tabindex="-1">Example output <a class="header-anchor" href="#example-output" aria-label="Permalink to &quot;Example output&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[rbq_wheel] wheel ownership requested (app 21)</span></span>
<span class="line"><span>[rbq_wheel] applied: HRW(tq=0.00 kd=0.500) HLW(tq=0.00 kd=0.500) FRW(tq=0.00 kd=0.500) FLW(tq=0.00 kd=0.500)</span></span>
<span class="line"><span>[rbq_wheel] applied: HRW(tq=1.00 kd=0.500) HLW(tq=1.00 kd=0.500) FRW(tq=1.00 kd=0.500) FLW(tq=1.00 kd=0.500)</span></span>
<span class="line"><span>[rbq_wheel] done - wheels released (kp = kd = torque = 0)</span></span></code></pre></div><p>Wheel order is <code>HRW HLW FRW FLW</code> (joints 12–15). On a classic CAN robot <code>kd</code> shows the board-rounded value, e.g. <code>0.501</code>.</p>`,16)])])}const u=s(n,[["render",i]]);export{k as __pageData,u as default};
